from pathlib import Path
root=Path(__file__).resolve().parents[2]
out=root/'explorations'
# Original editorial study: engraved notation, never an app capture.
def score():
 s=['<svg class="engraving" viewBox="0 0 1080 720" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Original illustrative piano study with handwritten phrase guidance; not an app screenshot"><rect width="1080" height="720" fill="#f7f1e3"/><g fill="#29282d"><text x="540" y="69" text-anchor="middle" font-family="Georgia,serif" font-size="32">A little further.</text><text x="540" y="95" text-anchor="middle" font-family="Georgia,serif" font-size="13" font-style="italic">A study for the week between lessons</text><text x="80" y="145" font-family="Georgia,serif" font-size="15" font-style="italic">Andante · with room to breathe</text><text x="998" y="145" text-anchor="end" font-family="monospace" font-size="9" letter-spacing="2">PROVA / STUDY NO. 01</text></g>']
 for sys,top in enumerate([190,425]):
  for staff in [top,top+102]:
   s.append(f'<path d="'+''.join(f'M80 {staff+i*12}H1000' for i in range(5))+'" fill="none" stroke="#918778" stroke-width=".8"/>')
  s.append(f'<path d="M80 {top}V{top+150}M75 {top-2}Q57 {top+25} 65 {top+56}Q70 {top+72} 59 {top+75}Q70 {top+79} 65 {top+94}Q57 {top+125} 75 {top+152}" fill="none" stroke="#29282d" stroke-width="1.6"/>')
  s.append(f'<g fill="#29282d" font-family="Georgia,serif"><text x="88" y="{top+43}" font-size="66">𝄞</text><text x="91" y="{top+139}" font-size="49">𝄢</text></g>')
  if sys==0:
   s.append(f'<g font-family="Georgia,serif" font-size="21" font-weight="bold" fill="#29282d"><text x="133" y="{top+22}">3</text><text x="133" y="{top+44}">4</text><text x="133" y="{top+124}">3</text><text x="133" y="{top+146}">4</text></g>')
  for bar in range(4):
   bx=165+bar*205
   s.append(f'<text x="{bx}" y="{top-14}" font-size="10" font-family="Georgia,serif" fill="#7e7367">{sys*4+bar+1}</text>')
   s.append(f'<path d="M{bx+192} {top}V{top+150}" stroke="#524a43" stroke-width="1"/>')
   # Three quarter beats; bar three a half note followed by quarter.
   ys=[36,24,18] if bar%2==0 else [12,24,30]
   for n,y in enumerate(ys):
    if bar==2 and n==1:continue
    x=bx+23+n*55; y+=top; hollow=bar==2 and n==0
    s.append(f'<ellipse cx="{x}" cy="{y}" rx="7.2" ry="4.8" transform="rotate(-20 {x} {y})" fill="'+('#f7f1e3' if hollow else '#29282d')+f'" stroke="#29282d" stroke-width="1.6"/><path d="M{x+6} {y-2}V{y-39}" stroke="#29282d" stroke-width="1.4"/>')
   # Dotted half-note harmony in the bass.
   for y in [top+120,top+132]:
    s.append(f'<ellipse cx="{bx+23}" cy="{y}" rx="7.2" ry="4.8" transform="rotate(-20 {bx+23} {y})" fill="#f7f1e3" stroke="#29282d" stroke-width="1.6"/><circle cx="{bx+38}" cy="{y-3}" r="1.6" fill="#29282d"/>')
   s.append(f'<path d="M{bx+17} {top+121}v46" stroke="#29282d" stroke-width="1.4"/>')
  s.append(f'<path d="M185 {top-44}Q310 {top-80} 480 {top-42}M596 {top-44}Q730 {top-73} 920 {top-40}" fill="none" stroke="#4d4541" stroke-width="1.2"/><text x="182" y="{top+82}" font-family="Georgia,serif" font-size="21" font-style="italic" fill="#29282d">p</text><path d="M392 {top+68}L484 {top+74}L392 {top+81}" fill="none" stroke="#524a43"/>')
 s.append('<g class="score-ink" fill="none" stroke="#7460ba" stroke-width="2.5" stroke-linecap="round"><path class="ink-stroke" pathLength="1" d="M569 196C589 173 628 189 626 221C627 253 585 261 568 240C553 219 562 201 573 194"/><path class="ink-stroke" pathLength="1" d="M559 270Q633 294 715 265M706 264l10 1-4 9"/><path class="ink-stroke" pathLength="1" d="M790 411q37-25 80 2"/></g><g class="ink-words" fill="#7460ba" font-family="Georgia,serif" font-style="italic"><text x="551" y="318" font-size="23" transform="rotate(-3 551 318)">let the phrase carry…</text><text x="784" y="393" font-size="17" transform="rotate(3 784 393)">listen here</text></g><path d="M80 650H1000" stroke="#d6ccba"/><g font-size="9" fill="#8d8174" font-family="monospace" letter-spacing="1.6"><text x="80" y="678">ORIGINAL EDITORIAL SCORE · ILLUSTRATIVE MARKS</text><text x="1000" y="678" text-anchor="end">01</text></g></svg>')
 return ''.join(s)
scorehtml=score();(out/'shared/score.svg').write_text(scorehtml)
def head(title,body):return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><meta name="theme-color" content="#15131c"><title>{title} — Prova</title><link rel="icon" href="/assets/favicon.png"><link rel="stylesheet" href="/explorations/shared/style.css"><script src="/explorations/shared/motion.js" defer></script></head><body class="{body}"><a class="skip" href="#main">Skip to the story</a>'''
def nav(letter):return f'''<header class="nav"><a class="wordmark" href="/explorations/" aria-label="Prova explorations"><img src="/assets/brandmark.png" width="26" height="32" alt="">prova<span class="edition">EXPLORATION {letter}</span></a><nav aria-label="Main"><a class="story-link" href="#story">The experience</a><a class="nav-cta" href="#join">Join the beta <span>↗</span></a></nav></header>'''
def phone(asset,cls='',alt='Historical Prova app capture'):
 return f'<figure class="phone {cls}"><img src="/assets/product/{asset}.jpg" width="880" height="1913" alt="{alt}" loading="lazy"></figure>'
